// Persistent IndexedDB cache for binary MVT plant tiles.
// Tiles are stored as ArrayBuffer keyed by "z/x/y".
// TTL is 7 days — plant data changes rarely.

const DB_NAME      = "PlantsMvtCache_v1"
const STORE_NAME   = "tiles"
const DB_VERSION   = 1
const TTL          = 7 * 24 * 60 * 60 * 1000

interface Entry { ts: number; buf: ArrayBuffer }

function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === "undefined") { reject(new Error("no idb")); return }
    const req = indexedDB.open(DB_NAME, DB_VERSION)
    req.onerror   = () => reject(req.error)
    req.onsuccess = () => resolve(req.result)
    req.onupgradeneeded = (e) => {
      const db = (e.target as IDBOpenDBRequest).result
      if (!db.objectStoreNames.contains(STORE_NAME)) db.createObjectStore(STORE_NAME)
    }
  })
}

export async function getMvtTile(key: string): Promise<ArrayBuffer | null> {
  try {
    const db  = await openDB()
    const tx  = db.transaction(STORE_NAME, "readonly")
    const req = tx.objectStore(STORE_NAME).get(key)
    return new Promise((resolve) => {
      req.onsuccess = () => {
        db.close()
        const e: Entry | undefined = req.result
        if (!e || Date.now() - e.ts > TTL) { resolve(null); return }
        resolve(e.buf)
      }
      req.onerror = () => { db.close(); resolve(null) }
    })
  } catch { return null }
}

export async function saveMvtTile(key: string, buf: ArrayBuffer): Promise<void> {
  try {
    const db = await openDB()
    const tx = db.transaction(STORE_NAME, "readwrite")
    tx.objectStore(STORE_NAME).put({ ts: Date.now(), buf } satisfies Entry, key)
    await new Promise<void>((resolve, reject) => {
      tx.oncomplete = () => { db.close(); resolve() }
      tx.onerror    = () => reject(tx.error)
    })
  } catch { /* non-fatal */ }
}
